#pragma config(Sensor, in1,    light,          sensorReflection)
#pragma config(Sensor, dgtl1,  ir,             sensorDigitalIn)
#pragma config(Motor,  port2,           idk,           tmotorServoContinuousRotation, openLoop)
//*!!Code automatically generated by 'ROBOTC' configuration wizard               !!*//

task main()
{

	while(true)
	{
		if(SensorValue(dgtl1) > 1)
		{
			motor(port2) = 127;
		}
		else
		{
			motor(port2) = 0;
		}
	}

}
